test('optimistic acceptance, empty gates, stale hashes, duplicate and missing scenes fail closed',()=>{const i=f.input(),w=f.writer(i),ri=c.reviewerInput(i,w);for(const mutate of [r=>r.records.pop(),r=>r.records.push(r.records[0]),r=>r.records[0].candidateHash='stale',r=>r.records[0].hardGates={},r=>{r.records[0].hardGates.b4CausesA5=false;}]){const r=f.review(ri);mutate(r);assert.throws(()=>c.validateReview(ri,r));}});
