test('retaining a weak original, stage directions and invented scene IDs are rejected',()=>{const i=f.input();for(const mutate of [w=>{w.records[0].firstPass.ratings.cardFidelity.score=2;w.records[0].firstPass.weightedTotal=82;},w=>w.records[0].beats[0].action='a movement',w=>w.records[0].exampleId='invented']){const w=structuredClone(f.writer(i));mutate(w);assert.throws(()=>c.validateWriter(i,w));}});
