const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),integration=require('../tools/local-audit/integration.cjs'),worker=require('../tools/local-audit/worker.cjs');
const temp=()=>fs.mkdtempSync(path.join(os.tmpdir(),'imprompt-runner-fixture-'));
test('interrupted integration resumes exact writes and refuses concurrent unrelated changes',()=>{const root=temp(),stage=temp(),dir=temp();c.save(path.join(root,'examples/authoring/single-scenes.json'),{old:true});c.save(path.join(root,'preserved.json'),{userEdit:true});c.save(path.join(stage,'examples/authoring/single-scenes.json'),{new:true});c.save(path.join(stage,'preserved.json'),{userEdit:true});const guard=c.fingerprint(root),journal=path.join(dir,'journal.json');integration.makeTransaction(root,stage,journal,'editorial/local-fixture',guard);assert.throws(()=>integration.applyTransaction(journal,1),/Fixture interruption/);assert.equal(c.read(journal).status,'prepared');integration.applyTransaction(journal);assert.deepEqual(c.fingerprint(root),c.fingerprint(stage));c.save(path.join(root,'preserved.json'),{anotherEditor:true});assert.throws(()=>integration.applyTransaction(journal),/Concurrent source conflict/);assert.equal(c.read(path.join(root,'preserved.json')).anotherEditor,true);});
test('transaction refuses changes to playable cards and preserves pre-existing work',()=>{const root=temp(),stage=temp(),dir=temp();c.save(path.join(root,'cards.json'),{wording:'original'});c.save(path.join(stage,'cards.json'),{wording:'unauthorized'});assert.throws(()=>integration.makeTransaction(root,stage,path.join(dir,'journal.json'),'editorial/local-fixture',c.fingerprint(root)),/Unexpected staging mutation/);assert.equal(c.read(path.join(root,'cards.json')).wording,'original');});
test('one live integration lock prevents a second runner or unsafe recovery',()=>{const {lock,recoverLock}=require('../tools/local-audit-runner.cjs'),root=temp(),release=lock(root,'fixture');assert.throws(()=>lock(root,'another'),/EEXIST/);assert.throws(()=>recoverLock(root),/still running/);release();assert.ok(!fs.existsSync(path.join(root,'.audit-runner.lock')));});
test('worker success without an output artifact is insufficient',async()=>{await assert.rejects(worker.invoke({executable:'fixture-only',role:'writer',input:f.input(),dir:temp(),rubricText:'fixture',timeoutMs:1000,runCommand:async()=>({code:0,timedOut:false})}),/without artifact/);});
test('saved worker proof resumes without another invocation; tampering stops reuse',async()=>{const dir=temp(),input=f.input();let calls=0;const runCommand=async(exe,args,cwd,log)=>{calls++;assert.ok(args.includes('read-only')&&args.includes('--ephemeral'));assert.ok(!args.some(a=>/dangerously|ignore-rules|add-dir/.test(a)));c.save(args[args.indexOf('--output-last-message')+1],f.writer(input));fs.writeFileSync(log+'.stdout.log',JSON.stringify({type:'turn.completed',usage:{input_tokens:12,output_tokens:7}})+'\n');return {code:0,timedOut:false,elapsedMs:3,log};};const opts={executable:'fixture-only',role:'writer',input,dir,rubricText:'fixture',timeoutMs:1000,runCommand};await worker.invoke(opts);await worker.invoke(opts);assert.equal(calls,1);c.save(path.join(dir,'writer.json'),{});await assert.rejects(worker.invoke(opts),/artifact changed/);});
test('unproven interrupted output and tool-using reviewer are never accepted',async()=>{const dir=temp();c.save(path.join(dir,'reviewer.json'),{});await assert.rejects(worker.invoke({executable:'fixture-only',role:'reviewer',input:{},dir,rubricText:'fixture',timeoutMs:100}),/Unproven partial/);const next=temp();await assert.rejects(worker.invoke({executable:'fixture-only',role:'reviewer',input:{records:[]},dir:next,rubricText:'fixture',timeoutMs:100,runCommand:async(exe,args,cwd,log)=>{c.save(args[args.indexOf('--output-last-message')+1],{});fs.writeFileSync(log+'.stdout.log',[{type:'item.completed',item:{type:'command_execution'}},{type:'turn.completed'}].map(JSON.stringify).join('\n'));return {code:0,timedOut:false};}}),/used tools/);});
test('queue bounds, explicit IDs and completed hashes come from fixtures, not release assumptions',()=>{const root=temp(),i=f.input(),source={records:{S01:{examples:i.records.map(r=>r.before)},S02:{examples:i.records.map(r=>({...r.before,id:r.before.id.replace('S01','S02')}))}}};c.save(path.join(root,'examples/authoring/single-scenes.json'),source);c.save(path.join(root,'examples/authoring/pair-scenes.json'),{});c.save(path.join(root,'examples/manifest.json'),{counts:{pairExamples:0}});c.save(path.join(root,'package.json'),{version:'9.9.9-fixture'});fs.mkdirSync(path.join(root,'editorial'));const q=c.plan(root,{id:'fixture',maxBatches:1});assert.equal(q.publicVersion,'9.9.9-fixture');assert.deepEqual(q.batches[0].scenes.map(s=>s.exampleId),['S01-single-a','S01-single-b','S02-single-a','S02-single-b']);assert.ok(q.batches[0].scenes.every(s=>s.sourceHash===c.hash(f.beats)));assert.throws(()=>c.plan(root,{maxBatches:6}));assert.throws(()=>c.plan(root,{maxAttempts:0}));assert.throws(()=>c.plan(root,{maxMinutes:0}));});

function repositoryFixture(){const root=temp(),records={};for(let n=1;n<=12;n++){const key='S'+String(n).padStart(2,'0');records[key]={title:'Fixture '+key,instruction:'Use the explicit fixture behavior.',contentVersion:'1',examples:f.input().records.map((r,i)=>{const scene=structuredClone(r.before);scene.id=key+'-single-'+(i?'b':'a');if(i)scene.beats[0].text='I brought a second torn map to plan our walk.';return scene;})};}c.save(path.join(root,'examples/authoring/single-scenes.json'),{records});c.save(path.join(root,'examples/authoring/stance-transfers.json'),{records:{}});c.save(path.join(root,'examples/authoring/pair-scenes.json'),{});c.save(path.join(root,'package.json'),{version:'9.9.9-fixture'});fs.mkdirSync(path.join(root,'editorial'));for(const file of ['AGENTS.md','CHECKPOINT-STATUS.md','docs/CODEX-HINT-AUDIT-HANDOFF.md','docs/COACH-REVIEW-RUBRIC.md']){fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});fs.writeFileSync(path.join(root,file),'Explicit artificial fixture, not a production review.');}fixtureBuild(root);return root;}
function fixtureBuild(root){const singles=c.read(path.join(root,'examples/authoring/single-scenes.json')).records;c.save(path.join(root,'examples/data/singles.fixture.json'),{records:Object.fromEntries(Object.entries(singles).map(([k,v])=>[k,v.examples]))});c.save(path.join(root,'examples/manifest.json'),{counts:{pairExamples:0},files:{singles:{plainUrl:'examples/data/singles.fixture.json'}}});}
function fixtureAdapters(root){const calls=[];return {root,calls,probe:()=>({version:'fixture-only; no Codex process'}),invoke:async({role,input,dir})=>{calls.push(role);let output;if(role==='writer'){output=f.writer(input);output.bindings=input.bindings.map(b=>({key:b.key,compatible:true,assessment:'FIXTURE ONLY: transfer fields and pair references inspected.'}));output.records[0].beats=structuredClone(output.records[0].beats);output.records[0].beats[4].text='I will bring my bicycle so we can ride home.';output.records[0].decision='revised';}else{output=f.review(input);output.bindings=input.bindings.map(b=>({key:b.key,compatible:true,assessment:'FIXTURE ONLY: transfer fields and pair references inspected.'}));}c.save(path.join(dir,role+'.json'),output);return {output,proof:{usage:[{input_tokens:10,output_tokens:5}],freshInvocation:true,outputHash:c.hash(output)}};},validate:async stage=>{fixtureBuild(stage);return ['build:examples','audit:all','test'].map(script=>({script,code:0,timedOut:false,fixture:true}));}};}
test('two-batch fixture stops after current, checkpoints one revision, resumes without redoing completed work',async()=>{const {run}=require('../tools/local-audit-runner.cjs'),root=repositoryFixture(),dir=path.join(root,'.audit-runs/fixture'),file=path.join(dir,'queue.json'),q=c.plan(root,{id:'fixture',maxBatches:2});q.guard=c.fingerprint(root);c.save(file,q);const adapters=fixtureAdapters(root),validate=adapters.validate;let validations=0;adapters.validate=async stage=>{validations++;if(validations===1)fs.writeFileSync(path.join(dir,'STOP_AFTER_CURRENT_BATCH'),'fixture stop');return validate(stage);};const first=await run(file,'fixture',true,adapters);assert.equal(first.stopReason,'stop-after-current-batch');assert.equal(first.completed,20);assert.equal(first.revised.length,1);assert.equal(first.retained.length,19);assert.equal(first.pending.length,4);assert.equal(adapters.calls.length,2);const before=c.read(file).batches[0];assert.equal(c.read(path.join(root,before.comparison)).mechanicallyChangedPairDialogue.length,0);fs.unlinkSync(path.join(dir,'STOP_AFTER_CURRENT_BATCH'));const second=await run(file,'fixture',true,adapters);assert.equal(second.stopReason,'bounded-queue-complete');assert.equal(second.completed,24);assert.equal(adapters.calls.length,4);const third=await run(file,'fixture',true,adapters);assert.equal(third.completed,24);assert.equal(adapters.calls.length,4);assert.equal(c.read(path.join(root,'package.json')).version,'9.9.9-fixture');assert.ok(!fs.existsSync(path.join(root,'releases')));});
test('fixture rejected second passes exhaust bounded retries without canonical edits or advancement',async()=>{const {run}=require('../tools/local-audit-runner.cjs'),root=repositoryFixture(),file=path.join(root,'.audit-runs/fixture/queue.json'),q=c.plan(root,{id:'fixture',maxBatches:2,maxAttempts:2});q.guard=c.fingerprint(root);c.save(file,q);const adapters=fixtureAdapters(root),invoke=adapters.invoke;adapters.invoke=async opts=>{const result=await invoke(opts);if(opts.role==='reviewer'){result.output.records[0].hardGates.b4CausesA5=false;result.output.records[0].accept=false;}return result;};const result=await run(file,'fixture',true,adapters);assert.equal(result.stopReason,'bounded-retries-exhausted');assert.equal(result.completed,0);assert.equal(result.failed.length,1);assert.equal(result.blocked.length,19);assert.equal(result.pending.length,23);assert.equal(adapters.calls.length,4);assert.deepEqual(c.fingerprint(root),q.guard);await run(file,'fixture',true,adapters);assert.equal(adapters.calls.length,4);});
test('failed fixture validation never integrates optimistic accepted reviews',async()=>{const {run}=require('../tools/local-audit-runner.cjs'),root=repositoryFixture(),file=path.join(root,'.audit-runs/fixture/queue.json'),q=c.plan(root,{id:'fixture',maxBatches:1});q.guard=c.fingerprint(root);c.save(file,q);const adapters=fixtureAdapters(root);adapters.validate=async()=>{throw Error('fixture audit failed');};const result=await run(file,'fixture',true,adapters);assert.equal(result.completed,0);assert.match(result.stopReason,/fixture audit failed/);assert.deepEqual(c.fingerprint(root),q.guard);assert.ok(c.read(file).batches[0].stage);});
test('queue follows exporter stance-before-drive order, not JSON object insertion order',()=>{const root=repositoryFixture(),file=path.join(root,'examples/authoring/single-scenes.json'),v=c.read(file);v.records={D01:{...v.records.S01,examples:v.records.S01.examples.map(s=>({...s,id:s.id.replace('S01','D01')}))},...v.records};c.save(file,v);assert.equal(c.discover(root).pendingKeys[0],'S01');assert.equal(c.discover(root).pendingKeys.at(-1),'D01');});
