test('a persisted batch boundary blocks later batches on repeated resume',async()=>{const {run}=require('../tools/local-audit-runner.cjs'),root=repositoryFixture(),file=path.join(root,'.audit-runs/fixture/queue.json'),q=c.plan(root,{id:'fixture',maxBatches:2});q.guard=c.fingerprint(root);c.save(file,q);const adapters=fixtureAdapters(root);adapters.throughBatch='batch-001';const result=await run(file,'fixture',true,adapters);assert.equal(result.completed,20);assert.equal(result.stopReason,'batch-boundary-reached');assert.equal(adapters.calls.length,2);delete adapters.throughBatch;await run(file,'fixture',true,adapters);assert.equal(adapters.calls.length,2);assert.equal(c.read(file).batches[1].status,'pending');});
