 const testDir=path.join(root,'.audit-runs/e2e-fixture'),small={...input,records:input.records.slice(0,2),bindings:input.bindings.slice(0,1)},tw=await adapters.invoke({role:'writer',input:small,dir:testDir}),ri=c.reviewerInput(small,tw.output),tr=await adapters.invoke({role:'reviewer',input:ri,dir:testDir});c.save(path.join(testDir,'writer.input.json'),small);for(const [role,out] of [['writer',tw.output],['reviewer',tr.output]])c.save(path.join(testDir,role+'.proof.json'),{freshInvocation:true,toolsUsed:false,outputHash:c.hash(out)});
 const evidenceFile=path.join(dir,'recovery-evidence.json'),evidence={batch:b.id,reason:'Explicit artificial fixture recovery authorization.',beforeGuard:q.guard,afterGuard:q.guard,reconciledFiles:[],endToEnd:{status:'passed',directory:testDir},reuseWriterDirectory:source};c.save(evidenceFile,evidence);const {recover}=require('../tools/local-audit/recovery.cjs');recover(file,b.id,evidenceFile,true);const after=c.read(file);assert.deepEqual(after.batches[0].attempts.slice(0,2),b.attempts);assert.deepEqual(after.limits,q.limits);assert.equal(after.batches[0].attempts.length,3);assert.equal(after.batches[0].recovery.startIndex,2);assert.equal(after.stopAfterBatch,'batch-001');assert.equal(after.batches[1].status,'pending');assert.ok(fs.existsSync(after.batches[0].recovery.snapshot));assert.equal(after.batches[0].scenes[0].attempts,2);assert.throws(()=>recover(file,b.id,evidenceFile,true));
