test('authorized model context excludes unrelated repository files and preserves accepted correction work',()=>{const r=require('../tools/local-audit-runner.cjs');const text=r.context('/nonexistent-do-not-read');assert.ok(!text.includes('AGENTS.md'));assert.ok(!text.includes('S01-single'));const input=f.input(),writer=f.writer(input),review=f.review(c.reviewerInput(input,writer));review.records[0].accept=false;const request=r.correctionRequest(writer,review),candidate=structuredClone(writer);candidate.records[0].beats=structuredClone(candidate.records[0].beats);candidate.records[0].beats[4].text='I will bring my bicycle for the trip home.';r.validateCorrection(candidate,request);candidate.records[1].reason='Unrequested alteration of an accepted candidate.';assert.throws(()=>r.validateCorrection(candidate,request),/already accepted/);candidate.records[1]=structuredClone(writer.records[1]);candidate.records[0].firstPass.weightedTotal=99;assert.throws(()=>r.validateCorrection(candidate,request),/original review/);});

