 const spec={schema:2,selectedIds:['S111-single-b'],repairs:[{key:'S111',changes:[change],supportingSeeds:seeds,authorAssessment:'FIXTURE A1 uses the exact cited seed; dialogue is preserved.'}]},fresh={records:[],bindings:[{key:'S111',compatible:true,assessment:'FIXTURE A1 source attribution agrees with the exact seeds.'}]};
