 assert.throws(()=>pa.changedPairs(pairs,[{...change,afterBeats:[]}]),/deep/);
 assert.throws(()=>pa.changedPairs([{...p,seedUse:'Changed after review'}],[change]),/before-record/);
 assert.throws(()=>br.blind(input,writer,{...spec,repairs:[{...spec.repairs[0],key:'S06'}]}),/Undemonstrated/);
 const beforeRoot=temp(),afterRoot=temp(),pairFile='examples/authoring/pair-scenes.json',doc={records:{'S111+D103':pairs,'S06+D49':[{id:'S06+D49-b',seedUse:'FIXTURE pending mismatch remains untouched.',beats:[]}]}};
 c.save(path.join(beforeRoot,pairFile),doc);c.save(path.join(afterRoot,pairFile),doc);br.applySource(afterRoot,spec);c.save(path.join(afterRoot,'editorial/local-fixture/binding-recovery.json'),spec);br.assertSourceChange(beforeRoot,afterRoot,'editorial/local-fixture');br.assertApplied(afterRoot,spec);
 const applied=c.read(path.join(afterRoot,pairFile));assert.deepEqual(applied.records['S06+D49'],doc.records['S06+D49']);assert.deepEqual(applied.records['S111+D103'].map(p=>p.beats),pairs.map(p=>p.beats));applied.records['S111+D103'][1].beats=[];c.save(path.join(afterRoot,pairFile),applied);assert.throws(()=>br.assertApplied(afterRoot,spec),/Applied provenance/);assert.throws(()=>br.assertSourceChange(beforeRoot,afterRoot,'editorial/local-fixture'),/Only explicit/);
 const generatedBefore={id:p.id,beats:p.beats,seedRefs:p.seedRefs,editorialStatus:'pair-review-pending'},generatedAfter={...generatedBefore,seedRefs:change.afterSeedRefs};pa.assertReferenceChange(generatedBefore,generatedAfter,change);assert.throws(()=>pa.assertReferenceChange(generatedBefore,generatedAfter),/Unrelated/);assert.throws(()=>pa.assertReferenceChange(generatedBefore,{...generatedAfter,editorialStatus:'internal-second-pass'},change),/more than/);assert.throws(()=>pa.assertReferenceChange(generatedBefore,{...generatedAfter,beats:[]},change),/more than/);
