test('observed WebSocket closing-handshake reconnect still requires exact completed output',()=>{
 const output={fixture:'complete'},retry={type:'error',message:'Reconnecting... 2/5 (stream disconnected before completion: WebSocket protocol error: Connection reset without closing handshake)'},message={type:'item.completed',item:{type:'agent_message',text:JSON.stringify(output)}},done={type:'turn.completed'};
 assert.deepEqual(worker.validateEvents([retry,message,done],output),[retry]);
 for(const events of [[retry,message],[retry,message,done,retry],[retry,{type:'turn.failed'},message,done],[{type:'error',message:'Reconnecting... 2/5 (permission denied)'},message,done],[{type:'error',message:'Reconnecting... 2/5 (stream disconnected before completion: WebSocket protocol error: UNKNOWN)'},message,done],[retry,{type:'item.completed',item:{type:'command_execution'}},message,done]])assert.throws(()=>worker.validateEvents(events,output));
 assert.throws(()=>worker.validateEvents([retry,message,done],{fixture:'mismatch'}));
});

test('proved recovered writer resolves only its classifier failure without resetting limits or editorial rounds',()=>{
 const tr=require('../tools/local-audit/transport-recovery.cjs'),policy=require('../tools/local-audit/editorial-policy.cjs'),base=temp(),source=path.join(base,'attempt-01'),dest=path.join(base,'attempt-03'),input=f.input(),writer=f.writer(input);fs.mkdirSync(source);const schema=path.join(source,'schema.json');c.save(schema,worker.schemas.writer);c.save(path.join(source,'writer.json'),writer);c.save(path.join(source,'writer.input.json'),input);c.save(path.join(source,'writer.process.json'),{code:0,timedOut:false,elapsedMs:1,command:['fixture','read-only','--ephemeral','--output-schema',schema]});fs.writeFileSync(path.join(source,'writer.prompt.txt'),worker.prompt('writer',input,'FIXTURE rubric','FIXTURE context',null));const retry={type:'error',message:'Reconnecting... 2/5 (stream disconnected before completion: WebSocket protocol error: Connection reset without closing handshake)'};const events=out=>[{type:'item.completed',item:{type:'agent_message',text:JSON.stringify(out)}},{type:'turn.completed'}];fs.writeFileSync(path.join(source,'writer.stdout.log'),[retry,...events(writer)].map(JSON.stringify).join('\n'));tr.recoverCompletedWriter(source,dest,input);
 const review=f.review(c.reviewerInput(input,writer));review.records[0].accept=false;c.save(path.join(dest,'reviewer.json'),review);c.save(path.join(dest,'reviewer.proof.json'),{freshInvocation:true,toolsUsed:false,outputHash:c.hash(review)});c.save(path.join(dest,'reviewer.process.json'),{code:0,timedOut:false,command:['fixture','read-only','--ephemeral']});fs.writeFileSync(path.join(dest,'reviewer.stdout.log'),events(review).map(JSON.stringify).join('\n'));
 const failed={id:'attempt-01',status:'failed',stage:'writer',error:'Worker reported failure'},b={correctionPolicy:{maxCorrections:2,authorizationHash:'fixture'},attempts:[failed,{id:'attempt-02',status:'failed',stage:'writer',error:'timedOut=true'},{id:'attempt-03',status:'rejected',writerReusedFrom:'attempt-01',writerReference:path.join(dest,'writer.json'),reviewReference:path.join(dest,'reviewer.json'),critique:{review}}]},q={limits:{maxAttempts:2}};assert.equal(policy.mayStart(q,b),false);const history=structuredClone(b.attempts),link={failedAttempt:'attempt-01',failedAttemptHash:c.hash(failed),recoveredAttempt:'attempt-03',writerProofHash:c.hash(c.read(path.join(dest,'writer.proof.json')))};b.resolvedTransportFailures=[link];assert.equal(policy.mayStart(q,b),true);assert.equal(policy.technicalLimit(q,b),2);assert.deepEqual(b.attempts,history);assert.deepEqual([...tr.resolvedFailures(b)],['attempt-01']);
 b.resolvedTransportFailures.push(link);assert.throws(()=>policy.mayStart(q,b),/Duplicate/);b.resolvedTransportFailures.pop();b.attempts[0].error='permission denied';assert.throws(()=>policy.mayStart(q,b));b.attempts[0]={...history[0]};
 b.attempts.push({status:'rejected',critique:{review}},{status:'rejected',critique:{review}});assert.equal(policy.mayStart(q,b),false);b.attempts.splice(3);c.save(path.join(source,'writer.process.json'),{code:1,timedOut:false});assert.throws(()=>policy.mayStart(q,b));
});
