 const writer=f.writer(input);writer.bindings=[{key:'S130',compatible:false,assessment:'FIXTURE demonstrated transfer wording mismatch.'}];const review=f.review(c.reviewerInput(input,writer));review.bindings=structuredClone(writer.bindings);
