test('D119 and D126 description scopes reject unrelated pairs, dialogue mutation and stale provenance',()=>{
 const pa=require('../tools/local-audit/provenance-amendment.cjs');
 for(const [key,pair] of [['D119','S118+D119'],['D126','S144+D126']]){
  const before={id:pair+'-a',beats:f.input().records[0].before.beats,seedRefs:[pair.split('+')[0]+'-single-a',key+'-single-a'],seedUse:'FIXTURE historical seed contribution only.',editorialStatus:'pending'},after={...before,seedUse:'FIXTURE historical contribution and current retained detail; pair semantic review remains pending.'};
  const change={exampleId:before.id,beforeSeedUse:before.seedUse,afterSeedUse:after.seedUse,beforeSeedRefs:before.seedRefs,afterSeedRefs:after.seedRefs,beforeRecordHash:c.hash(before),afterRecordHash:c.hash(after),reason:'FIXTURE ONLY explicit historical/current seed distinction.'},spec={schema:2,selectedIds:[key+'-single-a',key+'-single-b'],repairs:[{key,changes:[change],authorAssessment:'FIXTURE ONLY A1 concrete contribution; no production approval.'}]};
  pa.scope(spec);const applied=pa.changedPairs([before],[change]);assert.deepEqual(applied[0].beats,before.beats);assert.equal(applied[0].editorialStatus,'pending');
  const wrong=structuredClone(spec);wrong.repairs[0].changes[0].exampleId='S06+D49-b';assert.throws(()=>pa.scope(wrong),/Unrelated pair/);
  const stale={...change,beforeRecordHash:'stale'};assert.throws(()=>pa.changedPairs([before],[stale]),/conflict/);
  const changedDialogue={...after,beats:[...after.beats].reverse()};assert.throws(()=>pa.changedPairs([before],[{...change,afterRecordHash:c.hash(changedDialogue)}]),/conflict/);
  assert.throws(()=>pa.changedPairs([before],[{...change,afterSeedRefs:['S06-single-a',key+'-single-a']}]),/Cross-card/);
 }
});


test('successive provenance amendments require a unique complete hash chain',()=>{const {followChain}=require('../tools/local-audit/provenance-amendment.cjs'),edges=[{beforeRecordHash:'old',afterRecordHash:'middle'},{beforeRecordHash:'middle',afterRecordHash:'current'}];assert.equal(followChain('old','current',edges),'current');assert.throws(()=>followChain('old','unrecorded',edges),/Missing/);assert.throws(()=>followChain('old','current',[...edges,{beforeRecordHash:'old',afterRecordHash:'fork'}]),/ambiguous/);assert.throws(()=>followChain('old','current',[edges[0],{beforeRecordHash:'middle',afterRecordHash:'old'}]),/cycle/);});
